exempt = (input('exempt_assets') || {})['CKV_AWS_320'] || []

control 'CKV_AWS_320' do
  title 'Ensure Redshift clusters do not use the default database name'

  desc <<~DESC
    Checkov asserts this against Terraform. This profile asserts it against
